mcp:tool-listener.mcp:parameters-schema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "properties": {
    "legalName": { "type": "string", "description": "Registered legal entity name" },
    "registrationNumber": { "type": "string", "description": "Company registration number" },
    "jurisdiction": { "type": "string", "description": "Country/state of incorporation" },
    "industry": { "type": "string", "description": "Customer industry sector" },
    "requestedExposure": {
      "type": "object",
      "properties": {
        "currency": { "type": "string" },
        "amount": { "type": "number" }
      },
      "required": ["currency", "amount"]
    },
    "idempotencyKey": { "type": "string", "description": "Request idempotency key" }
  },
  "required": ["legalName", "registrationNumber", "jurisdiction", "requestedExposure"]
}
